def save(n,x):(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
old=json.loads((B/'FREEZE.json').read_text())
assert all(sha(B/n)==h for n,h in old['files'].items())
