e=lambda x:html.escape(str(x))
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Plant image and name audit v77</title><style>body{font:16px/1.55 system-ui;background:#10211e;color:#e7ede5;max-width:1150px;margin:32px auto;padding:0 20px}a{color:#9ee2bc}article{border:1px solid #48635a;border-radius:12px;padding:22px;margin:22px 0}h1,h2{color:#c8efcb}.notice{padding:18px;background:#344033}dt{font-weight:bold;margin-top:12px}dd{margin-left:0}code{color:#ffe1a1}small{color:#bdcfc6}</style><h1>Plant images & historical names</h1><p>v77 · 23 October 2026 · Evidence audit, no sound mapping</p><p class="notice">Six reproduced scans inspected at overview resolution. Castor and pansy remain useful visual candidates; none is a confirmed species. Historical spelling similarity is insufficient: the Centauria/knapweed pairing is not supported by the chosen historical edition.</p><p>Original notebook text was read in a scholarly volunteer transcription, not checked against autograph photographs. Unavailable originals and unresolved image details remain explicit. All earlier candidates remain in <a href="../plant-candidates-v76/report.html">the unchanged v76 snapshot</a>.</p>']
for a in A:
 ss=[s for s in slots if s['page']==a['page']]
 parts.append('<article><h2>'+a['page']+' — '+e(a['status'])+'</h2><p><a href="'+a['image']+'">Inspected manuscript image</a> · '+ ' / '.join(s['transcription']+': <code>'+e(s['first_token'])+'</code>' for s in ss)+'</p><small>Hand '+e(ss[0]['hand'])+'; Currier '+e(ss[0]['currier'])+'; '+e(ss[0]['section'])+'; paragraph text. H/F are alternate readings, not replication.</small><dl>')
 for k,label in [('observed','Visible features'),('supports','Supports'),('against','Mismatch / unresolved'),('original','Original-source audit'),('name','Historical-name compatibility')]:parts.append('<dt>'+label+'</dt><dd>'+e(a[k])+'</dd>')
 parts.append('<dt>Retained alternatives</dt><dd>'+e('; '.join(a['alternatives']))+'</dd></dl><p>'+ ' · '.join('<a href="'+e(S[r])+'">'+e(r)+'</a>' for r in a['refs'])+'</p><details><summary>H/F source lines</summary>'+''.join('<p>'+s['transcription']+' '+e(s['locus'])+': <code>'+e(' '.join(w or '[uncertain]' for w in s['full_line']))+'</code></p>' for s in ss)+'</details></article>')
